(function () {
  var slug = function (s) { return String(s || "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 40); };
  var out = [];
  var seen = {};
  $input.all().forEach(function (i) {
    var e = i.extracted || {};
    if (typeof e === "string") { try { e = JSON.parse(e.replace(/^```(?:json)?\s*|\s*```$/g, "").trim()); } catch (x) { e = {}; } }
    var org = String(e.company || "").trim();
    var event = String(e.event || "").trim();
    var link = i.link || i.url || "";
    if (!org || event.length < 15 || !/^https?:\/\//.test(link)) return;
    var id = "src-" + slug(org);
    if (seen[id]) return;
    seen[id] = true;
    var date = i.pubDate || i.published || i.date || "";
    var startup = /(seed|pre-seed|series|raised|funding|accelerator)/i.test(event + " " + (e.stage || ""));
    out.push({
      lead_id: id, org: org, website: e.website || "", country: e.country || "", stage: e.stage || "",
      hook: event, hook_source_url: link, hook_date: date, funding_date: startup ? date : "",
      audience: startup ? "startups" : "companies", status: "sourced", channel: "", handle: "", name: "", title: "",
      consent_basis: "", region: e.country || "", regulated: String(e.regulated_domain === true),
      employees: "", funds_evidence: "", tags: e.tags || "", score: "", source: "public_rss"
    });
  });
  return out;
})()
